<template><div v-if="open" class="message-backdrop" @click.self="$emit('close')"><aside class="message-drawer" role="dialog" aria-label="消息中心"><header><div><span class="eyebrow">消息中心</span><h2>发生了什么？</h2></div><button class="button ghost small" @click="$emit('close')">关闭</button></header><div class="message-actions"><select v-model="kind"><option value="">全部类型</option><option value="system">系统</option><option value="signal">信号</option><option value="data">数据</option><option value="execution">执行</option><option value="risk">风险</option><option value="configuration">配置</option></select><button class="button ghost small" @click="markAllMessagesRead">全部已读</button></div><div v-if="!filtered.length" class="structured-empty-state"><strong>没有消息</strong><p>系统只记录真实事件，不生成演示内容。</p></div><button v-for="item in filtered" :key="item.id" class="message-row" :class="[item.level,{unread:!item.read}]" @click="openItem(item)"><span>{{ item.level==='error'?'错误':item.level==='important'?'重要':'提示' }} · {{ time(item.occurred_at) }}</span><strong>{{ item.title }}</strong><p>{{ item.summary }}</p></button></aside></div></template>
<script setup>import { computed, ref } from 'vue'; import { markAllMessagesRead, markMessageRead, setActivePage, store } from '../stores/appStore.js'; defineProps({open:Boolean}); const emit=defineEmits(['close']); const kind=ref(''); const filtered=computed(()=>store.messages.filter(x=>!kind.value||x.kind===kind.value)); function time(v){return new Date(v).toLocaleString('zh-CN')} async function openItem(item){await markMessageRead(item.id); if(item.link){setActivePage(item.link.replace('#','')); emit('close')}}</script>
